from ortools.sat.python import cp_model
import itertools
import json

def solve_table_arrangement():
    booth_width = 10
    booth_height = 10

    table_types = ['standard', 'long', 'square']

    width_original = {
        'standard': 4,
        'long': 5,
        'square': 3
    }

    height_original = {
        'standard': 3,
        'long': 2,
        'square': 3
    }

    min_count = {
        'standard': 1,
        'long': 0,
        'square': 1
    }

    max_count = {
        'standard': 3,
        'long': 2,
        'square': 2
    }

    display_value = {
        'standard': 15,
        'long': 12,
        'square': 9
    }

    model = cp_model.CpModel()

    placed = {}
    for t in table_types:
        placed[t] = model.NewIntVar(min_count[t], max_count[t], f'placed_{t}')

    x = {}
    y = {}
    rotated = {}
    active = {}

    for t in table_types:
        for i in range(max_count[t]):
            x[(i, t)] = model.NewIntVar(0, booth_width, f'x_{i}_{t}')
            y[(i, t)] = model.NewIntVar(0, booth_height, f'y_{i}_{t}')
            rotated[(i, t)] = model.NewBoolVar(f'rotated_{i}_{t}')
            active[(i, t)] = model.NewBoolVar(f'active_{i}_{t}')

    for t in table_types:
        model.Add(placed[t] == sum(active[(i, t)] for i in range(max_count[t])))

    width = {}
    height = {}

    for t in table_types:
        for i in range(max_count[t]):
            width[(i, t)] = model.NewIntVar(0, booth_width, f'width_{i}_{t}')
            model.Add(width[(i, t)] == height_original[t]).OnlyEnforceIf(rotated[(i, t)])
            model.Add(width[(i, t)] == width_original[t]).OnlyEnforceIf(rotated[(i, t)].Not())

            height[(i, t)] = model.NewIntVar(0, booth_height, f'height_{i}_{t}')
            model.Add(height[(i, t)] == width_original[t]).OnlyEnforceIf(rotated[(i, t)])
            model.Add(height[(i, t)] == height_original[t]).OnlyEnforceIf(rotated[(i, t)].Not())

            model.Add(x[(i, t)] + width[(i, t)] <= booth_width).OnlyEnforceIf(active[(i, t)])
            model.Add(y[(i, t)] + height[(i, t)] <= booth_height).OnlyEnforceIf(active[(i, t)])

    for t in table_types:
        for i in range(max_count[t] - 1):
            model.AddImplication(active[(i + 1, t)], active[(i, t)])

    all_tables = []
    for t in table_types:
        for i in range(max_count[t]):
            all_tables.append((i, t))

    for idx1, (i1, t1) in enumerate(all_tables):
        for idx2, (i2, t2) in enumerate(all_tables):
            if idx1 >= idx2:
                continue

            left_of = model.NewBoolVar(f'left_{i1}_{t1}_{i2}_{t2}')
            right_of = model.NewBoolVar(f'right_{i1}_{t1}_{i2}_{t2}')
            below = model.NewBoolVar(f'below_{i1}_{t1}_{i2}_{t2}')
            above = model.NewBoolVar(f'above_{i1}_{t1}_{i2}_{t2}')

            w1 = width[(i1, t1)]
            h1 = height[(i1, t1)]
            w2 = width[(i2, t2)]
            h2 = height[(i2, t2)]

            model.Add(x[(i1, t1)] + w1 <= x[(i2, t2)]).OnlyEnforceIf([left_of, active[(i1, t1)], active[(i2, t2)]])
            model.Add(x[(i2, t2)] + w2 <= x[(i1, t1)]).OnlyEnforceIf([right_of, active[(i1, t1)], active[(i2, t2)]])
            model.Add(y[(i1, t1)] + h1 <= y[(i2, t2)]).OnlyEnforceIf([below, active[(i1, t1)], active[(i2, t2)]])
            model.Add(y[(i2, t2)] + h2 <= y[(i1, t1)]).OnlyEnforceIf([above, active[(i1, t1)], active[(i2, t2)]])

            model.AddBoolOr([left_of, right_of, below, above]).OnlyEnforceIf([active[(i1, t1)], active[(i2, t2)]])

    total_value = sum(placed[t] * display_value[t] for t in table_types)
    model.Maximize(total_value)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_utility_value = 0
        table_placements = []

        type_to_id = {'standard': 1, 'long': 2, 'square': 3}

        for t in table_types:
            total_utility_value += solver.Value(placed[t]) * display_value[t]

            for i in range(max_count[t]):
                if solver.Value(active[(i, t)]) == 1:
                    x_val = solver.Value(x[(i, t)])
                    y_val = solver.Value(y[(i, t)])
                    rot_val = solver.Value(rotated[(i, t)])
                    table_placements.append([
                        type_to_id[t],
                        x_val,
                        y_val,
                        rot_val
                    ])

        print(json.dumps({
            "total_utility_value": total_utility_value,
            "table_placements": table_placements
        }, separators=(',', ':')))
    else:
        print(json.dumps({
            "total_utility_value": 0,
            "table_placements": []
        }, separators=(',', ':')))

if __name__ == "__main__":
    solve_table_arrangement()
